create table balance_sheets (cash_and_equivalents decimal(19,2), equity decimal(19,2), quarter integer not null, total_assets decimal(19,2), total_capital decimal(19,2), year integer not null, id binary(16) not null, company_type varchar(31) not null check ((company_type in ('BANK','NON_BANK'))), company_id varchar(255) not null, primary key (id)) engine=InnoDB;
create table bank_balance_sheets (bad_debt decimal(20,2), balances_with_sbv decimal(19,2), convertible_other_papers decimal(19,2), customer_loan decimal(20,2), deposits_borrowings_others decimal(19,2), deposits_from_customers decimal(19,2), doubtful_debt decimal(20,2), gov_sbv_debt decimal(19,2), interbank_placements_loans decimal(19,2), investment_securities decimal(19,2), issuing_valuable_paper decimal(20,2), loans_to_customers decimal(19,2), provision_for_customer_loan_loss decimal(20,2), standard_debt decimal(20,2), substandard_debt decimal(20,2), total_equity decimal(20,2), total_liabilities decimal(19,2), trading_securities decimal(19,2), watchlist_debt decimal(20,2), id binary(16) not null, primary key (id)) engine=InnoDB;
create table bank_income_statements (credit_risk_provisions_expense decimal(20,2), interest_and_similar_income decimal(20,2), interest_expense decimal(19,2), net_fee_commission_income decimal(19,2), net_interest_income decimal(19,2), net_other_income_expenses decimal(19,2), net_profit decimal(19,2), total_operating_expense decimal(20,2), total_operating_income decimal(20,2), id binary(16) not null, primary key (id)) engine=InnoDB;
create table budgets (end_date date not null, is_recurring bit, recurring_start_date date, start_date date not null, target_amount decimal(38,2) not null, created_at datetime(6), updated_at datetime(6), category_id binary(16) not null, id binary(16) not null, user_id varchar(255) not null, primary key (id)) engine=InnoDB;
create table cash_flow_statements (financing_cashflow decimal(20,2), investing_cashflow decimal(20,2), operating_cashflow decimal(20,2), quarter integer not null, year integer not null, company_id varchar(255) not null, primary key (quarter, year, company_id)) engine=InnoDB;
create table categories (is_system bit not null, created_at datetime(6), updated_at datetime(6), id binary(16) not null, color varchar(255), icon varchar(255), name varchar(255) not null, user_id varchar(255) not null, type enum ('EXPENSE','INCOME','SAVING') not null, primary key (id)) engine=InnoDB;
create table chat_message_sources (page_number integer, score decimal(12,6), id bigint not null auto_increment, message_id varchar(36) not null, chunk_id varchar(100), source_title varchar(255), primary key (id)) engine=InnoDB;
create table chat_messages (cost_usd decimal(18,8), input_tokens integer, latency_ms integer, output_tokens integer, total_tokens integer, created_at datetime(6) not null, role varchar(16) not null, provider varchar(32), id varchar(36) not null, thread_id varchar(36) not null, model varchar(64), tool_call_id varchar(255), content LONGTEXT not null, tool_calls_json LONGTEXT, primary key (id)) engine=InnoDB;
create table chat_threads (last_year integer, created_at datetime(6) not null, updated_at datetime(6) not null, last_ticker varchar(16), id varchar(36) not null, user_id varchar(64) not null, context_summary TEXT, title varchar(255) not null, primary key (id)) engine=InnoDB;
create table companies (id varchar(10) not null, industry_node_id binary(16), company_type varchar(50) not null, exchange varchar(50) not null, company_name varchar(500), description varchar(2000), primary key (id)) engine=InnoDB;
create table company_dividends (exright_date date, issue_date date, record_date date, value decimal(38,2), company_id varchar(10) not null, id binary(16) not null, event_type varchar(50) not null, ratio varchar(100), event_title varchar(1000) not null, primary key (id)) engine=InnoDB;
create table company_shareholders (share_own_percent decimal(5,4), update_date date, quantity bigint, company_id varchar(10) not null, id binary(16) not null, shareholder_name varchar(500) not null, primary key (id)) engine=InnoDB;
create table event_publication (completion_attempts integer not null, completion_date datetime(6), last_resubmission_date datetime(6), publication_date datetime(6), id binary(16) not null, event_type varchar(255), listener_id varchar(255), serialized_event varchar(255), status enum ('COMPLETED','FAILED','PROCESSING','PUBLISHED','RESUBMITTED'), primary key (id)) engine=InnoDB;
create table financial_indicators (bvps decimal(19,2), cash_dividend decimal(20,6), cir decimal(20,6), cof decimal(20,6), current_ratio decimal(20,6), eps decimal(19,2), ev_over_ebitda decimal(20,6), gross_margin decimal(10,2), inventory_turnover decimal(20,6), ldr decimal(20,6), loanloss_reserves_to_npl decimal(20,6), net_margin decimal(10,2), nim decimal(20,6), npl_to_loan decimal(20,6), payout_ratio decimal(20,6), pb decimal(10,2), pe decimal(10,2), profit_growth decimal(20,6), ps decimal(10,2), quarter integer not null, roa decimal(10,2), roe decimal(10,2), sale_growth decimal(20,6), share_at_period_end decimal(20,2), shares_outstanding decimal(19,2), total_debt_over_equity decimal(20,6), year integer not null, yoea decimal(20,6), id binary(16) not null, company_type varchar(31) not null check ((company_type in ('BANK','NORMAL'))), company_id varchar(255) not null, primary key (id)) engine=InnoDB;
create table income_statements (profit_after_tax decimal(19,2), quarter integer not null, year integer not null, id binary(16) not null, company_type varchar(31) not null check ((company_type in ('BANK','NON_BANK'))), company_id varchar(255) not null, primary key (id)) engine=InnoDB;
create table industry_nodes (level integer not null, id binary(16) not null, parent_id binary(16), icb_code varchar(32), name_vi varchar(500) not null, detail_label varchar(2000), primary key (id)) engine=InnoDB;
create table invalidated_tokens (expiry_time datetime(6), id varchar(255) not null, primary key (id)) engine=InnoDB;
create table non_bank_balance_sheets (advances_from_customers decimal(19,2), convertible_bond decimal(20,2), fixed_assets decimal(19,2), in_progress_long_term_asset decimal(20,2), inventories decimal(19,2), long_term_borrowings decimal(19,2), long_term_receivables decimal(19,2), short_term_borrowings decimal(19,2), short_term_investments decimal(19,2), short_term_receivables decimal(19,2), total_liabilities decimal(19,2), id binary(16) not null, primary key (id)) engine=InnoDB;
create table non_bank_income_statements (cost_of_goods_sold decimal(20,2), gross_profit decimal(20,2), managing_expense decimal(20,2), net_profit decimal(19,2), net_revenue decimal(19,2), selling_expense decimal(20,2), total_revenue decimal(19,2), id binary(16) not null, primary key (id)) engine=InnoDB;
create table permissions (description varchar(255), name varchar(255) not null, primary key (name)) engine=InnoDB;
create table portfolio_assets (average_price decimal(19,2) not null, total_quantity decimal(19,0) not null, updated_at datetime(6), symbol varchar(10) not null, id binary(16) not null, portfolio_id binary(16) not null, primary key (id)) engine=InnoDB;
create table portfolios (cash_balance decimal(19,2) not null, created_at datetime(6), updated_at datetime(6), id binary(16) not null, name varchar(255) not null, user_id varchar(255) not null, primary key (id)) engine=InnoDB;
create table role_permissions (permission_name varchar(255) not null, role_name varchar(255) not null, primary key (permission_name, role_name)) engine=InnoDB;
create table roles (description varchar(255), name varchar(255) not null, primary key (name)) engine=InnoDB;
create table trade_transactions (fee_amount decimal(19,2), price decimal(19,2), quantity decimal(19,0), tax_amount decimal(19,2), total_amount decimal(19,2) not null, transaction_date datetime(6) not null, symbol varchar(10), id binary(16) not null, portfolio_id binary(16) not null, trade_type enum ('BUY','DEPOSIT','DIVIDEND','SELL','WITHDRAW') not null, primary key (id)) engine=InnoDB;
create table transactions (amount decimal(19,2) not null, created_at datetime(6), transaction_date datetime(6) not null, updated_at datetime(6), account_id binary(16) not null, category_id binary(16) not null, id binary(16) not null, note varchar(255), user_id varchar(255) not null, type enum ('EXPENSE','INCOME','SAVING') not null, primary key (id)) engine=InnoDB;
create table user_roles (role_name varchar(255) not null, user_id varchar(255) not null, primary key (role_name, user_id)) engine=InnoDB;
create table users (account_verified bit, dob date, is_active bit, is_biometric_enabled bit, deleted_at datetime(6), last_login datetime(6), register_date datetime(6), email varchar(255) not null, first_name varchar(255), id varchar(255) not null, last_name varchar(255), password varchar(255), username varchar(255) not null, provider enum ('GOOGLE','LOCAL'), primary key (id)) engine=InnoDB;
create table wealth_account (balance decimal(19,2) not null, include_in_net_worth bit not null, is_synced bit not null, created_at datetime(6), updated_at datetime(6), account_type_id binary(16) not null, id binary(16) not null, name varchar(256) not null, user_id varchar(255) not null, primary key (id)) engine=InnoDB;
create table wealth_account_type (is_debt bit not null, is_transaction_eligible bit not null, id binary(16) not null, color varchar(32), code varchar(64) not null, icon varchar(64), display_name varchar(128) not null, primary key (id)) engine=InnoDB;
create index idx_budget_recurring_end on budgets (user_id, is_recurring, end_date);
create index idx_chat_message_sources_message on chat_message_sources (message_id);
create index idx_chat_messages_thread_created on chat_messages (thread_id, created_at);
create index idx_chat_messages_thread_role on chat_messages (thread_id, role);
create index idx_chat_threads_user_updated on chat_threads (user_id, updated_at);
